    @Override protected void onCreate(Bundle b){
        super.onCreate(b);
        getWindow().setStatusBarColor(BG); getWindow().setNavigationBarColor(BG);
        db=new TradeDbHelper(this); prefs=getSharedPreferences("fastrade_prefs",MODE_PRIVATE);
        buildShell(); showDashboard();
    }

    private void buildShell(){
        root=new LinearLayout(this); root.setOrientation(LinearLayout.VERTICAL); root.setBackground(verticalGradient(BG,BG2));
        header=new LinearLayout(this); header.setOrientation(LinearLayout.VERTICAL); root.addView(header,new LinearLayout.LayoutParams(-1,-2));
        scroll=new ScrollView(this); scroll.setFillViewport(true); scroll.setOverScrollMode(View.OVER_SCROLL_NEVER);
        content=new LinearLayout(this); content.setOrientation(LinearLayout.VERTICAL); content.setPadding(dp(16),dp(4),dp(16),dp(22)); scroll.addView(content); root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));
        nav=row(); nav.setGravity(Gravity.CENTER); nav.setBackgroundColor(Color.rgb(6,20,31)); nav.setPadding(dp(6),dp(2),dp(6),dp(2));
        addNav("⌂","Home",0,()->showDashboard()); addNav("＋","Nuova",1,()->showNewOperation()); addNav("▤","Diario",2,()->showJournal()); addNav("▥","Statistiche",3,()->showStats()); addNav("●","Bankroll",4,()->showBankroll());
        root.addView(nav,new LinearLayout.LayoutParams(-1,dp(66)));
        root.setOnApplyWindowInsetsListener((v,insets)->{int top=insets.getSystemWindowInsetTop();int bottom=insets.getSystemWindowInsetBottom();root.setPadding(0,top,0,0);LinearLayout.LayoutParams lp=(LinearLayout.LayoutParams)nav.getLayoutParams();lp.height=dp(66)+bottom;nav.setLayoutParams(lp);nav.setPadding(dp(6),dp(2),dp(6),bottom+dp(2));return insets;});
        setContentView(root); root.requestApplyInsets();
    }

    private void renderHeader(String title,int navIndex){
        header.removeAllViews();
        if(navIndex==0){
            LinearLayout bar=row(); bar.setGravity(Gravity.CENTER_VERTICAL); bar.setPadding(dp(18),dp(9),dp(18),dp(8));
            ImageView logo=new ImageView(this); logo.setImageResource(getResources().getIdentifier("ic_launcher","mipmap",getPackageName())); logo.setScaleType(ImageView.ScaleType.CENTER_CROP); bar.addView(logo,new LinearLayout.LayoutParams(dp(50),dp(50)));
            LinearLayout brand=new LinearLayout(this);brand.setOrientation(LinearLayout.VERTICAL);brand.setPadding(dp(10),0,0,0);TextView n=text("FasTrade",25,TEXT,true);brand.addView(n);TextView s=text("SPORTS TRADING",9,BLUE,true);s.setLetterSpacing(.22f);brand.addView(s);bar.addView(brand,new LinearLayout.LayoutParams(0,-2,1));
            TextView gear=text("⚙",22,CYAN,false);gear.setGravity(Gravity.CENTER);gear.setBackground(round(Color.argb(40,25,135,255),18,Color.argb(70,25,135,255)));gear.setOnClickListener(v->showToolsScreen());bar.addView(gear,new LinearLayout.LayoutParams(dp(42),dp(42)));header.addView(bar);
            TextView pay=text("DISCIPLINA  |  STRATEGIA  |  RISULTATI",8,Color.rgb(164,191,215),false);pay.setLetterSpacing(.12f);pay.setPadding(dp(78),0,0,dp(8));header.addView(pay);
        }else if(navIndex==-1){
            LinearLayout bar=row();bar.setGravity(Gravity.CENTER_VERTICAL);bar.setPadding(dp(16),dp(9),dp(16),dp(7));TextView back=text("‹",34,TEXT,false);back.setGravity(Gravity.CENTER);back.setOnClickListener(v->showDashboard());bar.addView(back,new LinearLayout.LayoutParams(dp(42),dp(46)));TextView t=text("FasTrade",18,TEXT,true);t.setGravity(Gravity.CENTER);bar.addView(t,new LinearLayout.LayoutParams(0,dp(46),1));TextView empty=text("",20,TEXT,false);bar.addView(empty,new LinearLayout.LayoutParams(dp(42),dp(46)));header.addView(bar);
        }else{
            LinearLayout bar=row();bar.setGravity(Gravity.CENTER_VERTICAL);bar.setPadding(dp(14),dp(8),dp(14),dp(6));
            TextView back=text("‹",34,TEXT,false);back.setGravity(Gravity.CENTER);back.setOnClickListener(v->showDashboard());bar.addView(back,new LinearLayout.LayoutParams(dp(42),dp(46)));
            TextView t=text(title,18,TEXT,true);t.setGravity(Gravity.CENTER);bar.addView(t,new LinearLayout.LayoutParams(0,dp(46),1));
            TextView spacer=text(navIndex==3?"⌁":"",20,CYAN,false);spacer.setGravity(Gravity.CENTER);bar.addView(spacer,new LinearLayout.LayoutParams(dp(42),dp(46)));header.addView(bar);
        }
    }

    private void addNav(String icon,String label,int index,Runnable r){LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setGravity(Gravity.CENTER);TextView i=text(icon,18,MUTED,true),t=text(label,9,MUTED,false);i.setGravity(Gravity.CENTER);t.setGravity(Gravity.CENTER);box.addView(i,new LinearLayout.LayoutParams(-1,dp(27)));box.addView(t,new LinearLayout.LayoutParams(-1,dp(20)));box.setOnClickListener(v->r.run());nav.addView(box,new LinearLayout.LayoutParams(0,-1,1));navItems.add(new NavItem(box,i,t,index));}
    private void selectNav(int index){for(NavItem n:navItems){int c=n.index==index?BLUE:MUTED;n.icon.setTextColor(c);n.label.setTextColor(c);n.icon.setScaleX(n.index==index?1.08f:1f);n.icon.setScaleY(n.index==index?1.08f:1f);}}
    private void page(String title,int navIndex){content.removeAllViews();scroll.scrollTo(0,0);selectNav(navIndex);renderHeader(title,navIndex);}

    private void showDashboard(){page("",0);Stats s=stats();
        content.addView(new HeroBankCard(this,s),new LinearLayout.LayoutParams(-1,dp(155)));
        LinearLayout kr=row();kr.addView(kpiSpark("Net Profit",money.format(s.netProfit),s.netProfit>=0?GREEN:RED,0),wp());kr.addView(kpiSpark("ROI",s.totalStake==0?"0,0%":pct.format(s.roi),s.roi>=0?GREEN:RED,1),wp());kr.addView(kpiSpark("Win Rate",s.totalTrades==0?"0,0%":pct.format(s.winPct),CYAN,2),wp());content.addView(kr);
        LinearLayout sh=row();sh.setGravity(Gravity.CENTER_VERTICAL);sh.addView(section("Andamento Bankroll"),new LinearLayout.LayoutParams(0,-2,1));LinearLayout chips=row();chips.addView(chip("7G",dashDays==7,v->{dashDays=7;showDashboard();}));chips.addView(chip("1M",dashDays==30,v->{dashDays=30;showDashboard();}));chips.addView(chip("3M",dashDays==90,v->{dashDays=90;showDashboard();}));chips.addView(chip("1A",dashDays==365,v->{dashDays=365;showDashboard();}));sh.addView(chips);content.addView(sh);
        LinearLayout chartCard=card(Color.rgb(4,21,32));chartCard.setPadding(dp(8),dp(5),dp(8),dp(3));chartCard.addView(new BankrollChart(this,bankrollSeries(s.startingBank,dashDays),dashDays,true),new LinearLayout.LayoutParams(-1,dp(176)));content.addView(chartCard);
        LinearLayout todayHead=row();todayHead.setGravity(Gravity.CENTER_VERTICAL);todayHead.addView(section("Oggi"),new LinearLayout.LayoutParams(0,-2,1));todayHead.addView(text(new SimpleDateFormat("d MMM yyyy",Locale.ITALY).format(new Date()),10,MUTED,false));content.addView(todayHead);
        double td=todayProfit();LinearLayout tr=row();tr.addView(kpi("Profitto Giornaliero",money.format(td),td>=0?GREEN:RED),wp());tr.addView(kpi("Target 1%",money.format(s.currentBank*.01),GOLD),wp());tr.addView(kpi("Operazioni",String.valueOf(todayTrades()),BLUE),wp());content.addView(tr);
        if(s.startingBank==0)content.addView(action("IMPOSTA STARTING BANK",BLUE,v->askStartingBank()));
    }

    private void showNewOperation(){page("Nuova Operazione",1);LinearLayout tabs=row();tabs.addView(tab("Operazione",true,null),wp());tabs.addView(tab("Calcolo Stake",false,v->toast("Il calcolo stake è integrato nell'operazione.")),wp());content.addView(tabs);
        EditText date=input(false,"Data");date.setText(new SimpleDateFormat("dd/MM/yyyy",Locale.ITALY).format(new Date()));content.addView(field("Data",date));Spinner sport=spinner(SPORTS);content.addView(field("Sport",sport));EditText match=input(false,"Es. Juventus - Lazio");content.addView(field("Match",match));Spinner market=spinner(MARKETS);content.addView(field("Mercato",market));List<String> sn=getStrategies();Spinner strategy=spinner(sn.toArray(new String[0]));content.addView(field("Strategia",strategy));
        LinearLayout mini=row();EditText minute=input(true,"45");EditText tranche=input(true,"1");EditText stakePct=input(true,"2,0");mini.addView(fieldMini("Minuto ingresso",minute),wp());mini.addView(fieldMini("Tranche",tranche),wp());mini.addView(fieldMini("Stake %",stakePct),wp());content.addView(mini);
        TextView stakeCard=text("Stake € (calcolato)\n"+money.format(0),17,GREEN,true);stakeCard.setGravity(Gravity.CENTER);stakeCard.setPadding(dp(10),dp(8),dp(10),dp(8));stakeCard.setBackground(horizontalGradient(Color.rgb(1,89,61),Color.rgb(2,55,42),14,GREEN));content.addView(stakeCard,new LinearLayout.LayoutParams(-1,dp(64)));
        EditText odds=input(true,"1,75");content.addView(field("Quota ingresso",odds));final boolean[] win={true};LinearLayout wr=row();Button wb=smallButton("WIN",GREEN),lb=smallButton("LOSE",SURFACE2);wr.addView(wb,wp());wr.addView(lb,wp());wb.setOnClickListener(v->{win[0]=true;wb.setBackground(horizontalGradient(GREEN,Color.rgb(1,162,103),10,0));lb.setBackground(round(SURFACE2,10,LINE));});lb.setOnClickListener(v->{win[0]=false;lb.setBackground(horizontalGradient(RED,Color.rgb(171,38,55),10,0));wb.setBackground(round(SURFACE2,10,LINE));});content.addView(field("Risultato",wr));
        EditText pl=input(true,"Es. 18,75");content.addView(field("Profit / Loss €",pl));EditText rating=input(false,"A / B / C");content.addView(field("Voto operazione",rating));EditText notes=input(false,"Aggiungi una nota...");notes.setMinHeight(dp(58));content.addView(field("Note (opzionale)",notes));
        Runnable calc=()->{Stats st=stats();double p=parse(stakePct.getText().toString());stakeCard.setText("Stake € (calcolato)\n"+money.format(st.currentBank*p/100d));};stakePct.setOnFocusChangeListener((v,f)->{if(!f)calc.run();});
        content.addView(action("SALVA OPERAZIONE",BLUE,v->{double result=parse(pl.getText().toString());if(result!=0)result=win[0]?Math.abs(result):-Math.abs(result);Stats st=stats();double p=parse(stakePct.getText().toString());TradeDbHelper.Operation o=new TradeDbHelper.Operation();o.date=date.getText().toString().trim();o.match=match.getText().toString().trim();o.sport=String.valueOf(sport.getSelectedItem());o.marketType=String.valueOf(market.getSelectedItem());o.strategy=String.valueOf(strategy.getSelectedItem());o.market=o.strategy;o.minute=minute.getText().toString().trim();o.tranche=tranche.getText().toString().trim();o.stakePct=p;o.stakeEur=st.currentBank*p/100d;o.odds=parse(odds.getText().toString());o.result=result;o.rating=rating.getText().toString().trim();o.notes=notes.getText().toString().trim();db.addOperation(o);toast("Operazione salvata");showJournal();}));
    }

    private void showJournal(){page("Diario Operazioni",2);LinearLayout filters=row();String[] fs={"Tutte","Oggi","Settimana","Mese"};for(int i=0;i<fs.length;i++){final int idx=i;filters.addView(chip(fs[i],journalFilter==i,v->{journalFilter=idx;showJournal();}),wp());}content.addView(filters);List<TradeDbHelper.Operation> ops=filteredOps();if(ops.isEmpty()){content.addView(empty("Nessuna operazione in questo periodo."));return;}String last="";for(TradeDbHelper.Operation o:ops){if(!o.date.equals(last)){LinearLayout dh=row();dh.setPadding(dp(4),dp(12),dp(4),dp(5));dh.addView(text(o.date,12,TEXT,true),new LinearLayout.LayoutParams(0,-2,1));double dt=dayTotal(o.date);dh.addView(text(sign(dt)+money.format(Math.abs(dt)),12,dt>=0?GREEN:RED,true));content.addView(dh);last=o.date;}LinearLayout c=card(Color.rgb(5,23,35));c.setPadding(dp(13),dp(10),dp(13),dp(10));LinearLayout top=row();top.setGravity(Gravity.CENTER_VERTICAL);TextView sportIcon=text(o.sport.equalsIgnoreCase("Tennis")?"◉":"⚽",18,Color.rgb(208,222,235),false);sportIcon.setGravity(Gravity.CENTER);top.addView(sportIcon,new LinearLayout.LayoutParams(dp(34),dp(44)));LinearLayout info=new LinearLayout(this);info.setOrientation(LinearLayout.VERTICAL);info.addView(text(o.match.isEmpty()?"—":o.match,13,TEXT,true));String meta=(o.marketType.isEmpty()?o.market:o.marketType)+" | "+(o.strategy.isEmpty()?o.market:o.strategy);info.addView(text(meta,9,MUTED,false));String meta2=(o.minute.isEmpty()?"":o.minute+"' | ")+(o.odds>0?"@"+one.format(o.odds)+" | ":"")+money.format(o.stakeEur);info.addView(text(meta2,9,Color.rgb(145,171,196),false));top.addView(info,new LinearLayout.LayoutParams(0,-2,1));LinearLayout rhs=new LinearLayout(this);rhs.setOrientation(LinearLayout.VERTICAL);rhs.setGravity(Gravity.RIGHT);TextView badge=text(o.result>=0?"WIN":"LOSE",10,Color.WHITE,true);badge.setGravity(Gravity.CENTER);badge.setBackground(round(o.result>=0?Color.rgb(3,126,82):Color.rgb(187,40,54),9,0));rhs.addView(badge,new LinearLayout.LayoutParams(dp(60),dp(28)));TextView pv=text(sign(o.result)+money.format(Math.abs(o.result)),13,o.result>=0?GREEN:RED,true);pv.setGravity(Gravity.RIGHT);pv.setPadding(0,dp(5),0,0);rhs.addView(pv);top.addView(rhs);c.addView(top);c.setOnLongClickListener(v->{confirmDelete(o.id);return true;});content.addView(c);}}

    private void showStats(){page("Statistiche",3);HorizontalScrollView hs=new HorizontalScrollView(this);hs.setHorizontalScrollBarEnabled(false);LinearLayout tabs=row();String[] names={"Panoramica","Strategie","Sport","Mese","Personalizzato"};for(int i=0;i<names.length;i++){final int x=i;tabs.addView(tab(names[i],statsTab==i,v->{statsTab=x;showStats();}),new LinearLayout.LayoutParams(dp(i==4?112:88),-2));}hs.addView(tabs);content.addView(hs);
        if(statsTab==0){showAnalyticsOverview();return;}
        List<TradeDbHelper.Operation> ops=db.allOperations();Map<String,SS> map=new LinkedHashMap<>();SimpleDateFormat in=new SimpleDateFormat("dd/MM/yyyy",Locale.ITALY),out=new SimpleDateFormat("MMM yyyy",Locale.ITALY);for(TradeDbHelper.Operation o:ops){if(isMovement(o))continue;String k;if(statsTab==2)k=o.sport.isEmpty()?"Altro":o.sport;else if(statsTab==3){try{k=out.format(in.parse(o.date));}catch(Exception e){k="Senza data";}}else k=o.strategy.isEmpty()?o.market:o.strategy;SS x=map.get(k);if(x==null){x=new SS();map.put(k,x);}x.op++;if(o.result>0)x.win++;else if(o.result<0)x.lose++;x.profit+=o.result;x.stake+=o.stakeEur;}if(map.isEmpty()){content.addView(empty("Registra alcune operazioni per vedere le statistiche."));return;}
        LinearLayout table=card(Color.rgb(4,20,31));LinearLayout hd=row();hd.addView(cell(statsTab==2?"Sport":statsTab==3?"Mese":"Strategia",9,MUTED,true,2.0f));hd.addView(cell("Op.",9,MUTED,true,.7f));hd.addView(cell("Win",9,MUTED,true,.7f));hd.addView(cell("Lose",9,MUTED,true,.7f));hd.addView(cell("Win %",9,MUTED,true,1f));hd.addView(cell("Profit",9,MUTED,true,1.3f));table.addView(hd);for(Map.Entry<String,SS> e:map.entrySet()){SS x=e.getValue();LinearLayout rr=row();rr.addView(cell(e.getKey(),10,TEXT,true,2.0f));rr.addView(cell(String.valueOf(x.op),10,TEXT,false,.7f));rr.addView(cell(String.valueOf(x.win),10,GREEN,false,.7f));rr.addView(cell(String.valueOf(x.lose),10,TEXT,false,.7f));rr.addView(cell(x.op==0?"0%":one.format(100d*x.win/x.op)+"%",10,TEXT,false,1f));rr.addView(cell(money.format(x.profit),10,x.profit>=0?GREEN:RED,true,1.3f));table.addView(rr);}content.addView(table);
        content.addView(section("Distribuzione Profitto"));content.addView(new DonutCard(this,map),new LinearLayout.LayoutParams(-1,dp(210)));
    }

    private void showAnalyticsOverview(){Stats s=stats();LinearLayout k=row();k.addView(kpiSpark("Profitto Totale",money.format(s.netProfit),s.netProfit>=0?GREEN:RED,0),wp());k.addView(kpiSpark("ROI",s.totalStake==0?"0,0%":pct.format(s.roi),GREEN,1),wp());k.addView(kpiSpark("Win Rate",s.totalTrades==0?"0,0%":pct.format(s.winPct),CYAN,2),wp());content.addView(k);
        LinearLayout h=row();h.setGravity(Gravity.CENTER_VERTICAL);h.addView(section("Andamento Profitto"),new LinearLayout.LayoutParams(0,-2,1));LinearLayout chips=row();chips.addView(chip("7G",dashDays==7,v->{dashDays=7;showStats();}));chips.addView(chip("1M",dashDays==30,v->{dashDays=30;showStats();}));chips.addView(chip("3M",dashDays==90,v->{dashDays=90;showStats();}));chips.addView(chip("1A",dashDays==365,v->{dashDays=365;showStats();}));h.addView(chips);content.addView(h);
        LinearLayout lineCard=card(Color.rgb(4,20,31));lineCard.setPadding(dp(8),dp(6),dp(8),dp(4));lineCard.addView(new DualLineChart(this,bankrollSeries(s.startingBank,dashDays),profitSeries(dashDays),dashDays),new LinearLayout.LayoutParams(-1,dp(190)));content.addView(lineCard);
        content.addView(section("Profitto per Strategia"));Map<String,SS> byStr=strategyMap();content.addView(new ProfitBars(this,byStr),new LinearLayout.LayoutParams(-1,dp(Math.max(170,Math.min(320,70+byStr.size()*30)))));
        content.addView(section("Distribuzione Profitto"));content.addView(new DonutCard(this,byStr),new LinearLayout.LayoutParams(-1,dp(210)));
    }

    private void showBankroll(){page("Bankroll",4);Stats s=stats();LinearLayout r=row();r.addView(kpi("Starting Bank",money.format(s.startingBank),TEXT),wp());r.addView(kpi("Current Bank",money.format(s.currentBank),GREEN),wp());content.addView(r);LinearLayout r2=row();r2.addView(kpi("Depositi",money.format(s.deposits),BLUE),wp());r2.addView(kpi("Prelievi",money.format(Math.abs(s.withdrawals)),TEXT),wp());r2.addView(kpi("Net Profit",money.format(s.netProfit),s.netProfit>=0?GREEN:RED),wp());content.addView(r2);
        LinearLayout tabs=row();tabs.addView(tab("Grafico",bankTab==0,v->{bankTab=0;showBankroll();}),wp());tabs.addView(tab("Movimenti",bankTab==1,v->{bankTab=1;showBankroll();}),wp());content.addView(tabs);
        if(bankTab==0){LinearLayout range=row();range.setGravity(Gravity.RIGHT);range.addView(chip("7G",bankDays==7,v->{bankDays=7;showBankroll();}));range.addView(chip("1M",bankDays==30,v->{bankDays=30;showBankroll();}));range.addView(chip("3M",bankDays==90,v->{bankDays=90;showBankroll();}));range.addView(chip("1A",bankDays==365,v->{bankDays=365;showBankroll();}));content.addView(range);LinearLayout chartCard=card(Color.rgb(4,20,31));chartCard.setPadding(dp(7),dp(5),dp(7),dp(2));chartCard.addView(new BankrollChart(this,bankrollSeries(s.startingBank,bankDays),bankDays,true),new LinearLayout.LayoutParams(-1,dp(205)));content.addView(chartCard);}else{showMovementsList();}
        content.addView(section("Obiettivi"));content.addView(goal("Target Giornaliero 1%",todayProfit(),s.currentBank*.01));content.addView(goal("Target Settimanale 5%",weekProfit(),s.currentBank*.05));content.addView(action("MODIFICA STARTING BANK",BLUE2,v->askStartingBank()));content.addView(action("REGISTRA DEPOSITO / PRELIEVO",GREEN,v->movementDialog()));content.addView(action("GESTIONE STRATEGIE",BLUE,v->showStrategyManager())); }

    private void showMovementsList(){List<TradeDbHelper.Operation> all=db.allOperations();boolean any=false;for(TradeDbHelper.Operation o:all){if(!isMovement(o))continue;any=true;LinearLayout c=card(SURFACE);LinearLayout rr=row();LinearLayout left=new LinearLayout(this);left.setOrientation(LinearLayout.VERTICAL);left.addView(text(o.market.equals("DEPOSIT")?"Deposito":"Prelievo",13,TEXT,true));left.addView(text(o.date,10,MUTED,false));rr.addView(left,new LinearLayout.LayoutParams(0,-2,1));LinearLayout right=new LinearLayout(this);right.setOrientation(LinearLayout.VERTICAL);right.setGravity(Gravity.RIGHT);TextView amt=text((o.result>=0?"+ ":"- ")+money.format(Math.abs(o.result)),13,o.result>=0?GREEN:RED,true);amt.setGravity(Gravity.RIGHT);right.addView(amt);Button del=smallButton("ELIMINA",Color.rgb(145,35,45));del.setOnClickListener(v->confirmDeleteMovement(o.id));right.addView(del,new LinearLayout.LayoutParams(dp(86),dp(36)));rr.addView(right);c.addView(rr);content.addView(c);}if(!any)content.addView(empty("Nessun deposito o prelievo registrato."));}

    private void movementDialog(){LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(dp(18),dp(5),dp(18),0);Spinner sp=spinner(new String[]{"Deposito","Prelievo"});EditText amount=input(true,"Importo €");box.addView(field("Tipo",sp));box.addView(field("Importo",amount));new AlertDialog.Builder(this).setTitle("Movimento bankroll").setView(box).setPositiveButton("Salva",(d,w)->{double a=Math.abs(parse(amount.getText().toString()));TradeDbHelper.Operation o=new TradeDbHelper.Operation();o.date=new SimpleDateFormat("dd/MM/yyyy",Locale.ITALY).format(new Date());o.market=sp.getSelectedItemPosition()==0?"DEPOSIT":"WITHDRAW";o.strategy=o.market;o.marketType=o.market;o.sport="";o.result=sp.getSelectedItemPosition()==0?a:-a;db.addOperation(o);bankTab=1;showBankroll();}).setNegativeButton("Annulla",null).show();}

