    private void exportCsv(){Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("text/csv");i.putExtra(Intent.EXTRA_TITLE,"FasTrade_Trades.csv");startActivityForResult(i,REQ_EXPORT_CSV);}
    private void backupData(){Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("application/octet-stream");i.putExtra(Intent.EXTRA_TITLE,"FasTrade_Backup.db");startActivityForResult(i,REQ_BACKUP);}
    private void restoreData(){new AlertDialog.Builder(this).setTitle("Ripristino dati").setMessage("Il ripristino sostituirà i dati attuali con quelli del backup selezionato.").setPositiveButton("Continua",(d,w)->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("*/*");startActivityForResult(i,REQ_RESTORE);}).setNegativeButton("Annulla",null).show();}
    private void openAppSettings(){Intent i=new Intent(Settings.ACTION_APPLICATION_DETAILS_SETTINGS,Uri.parse("package:"+getPackageName()));startActivity(i);}

    @Override protected void onActivityResult(int requestCode,int resultCode,Intent data){super.onActivityResult(requestCode,resultCode,data);if(resultCode!=RESULT_OK||data==null||data.getData()==null)return;Uri uri=data.getData();try{if(requestCode==REQ_EXPORT_CSV)writeCsv(uri);else if(requestCode==REQ_BACKUP)writeBackup(uri);else if(requestCode==REQ_RESTORE)readBackup(uri);}catch(Exception e){toast("Errore: "+e.getMessage());}}
    private void writeCsv(Uri uri)throws Exception{OutputStream os=getContentResolver().openOutputStream(uri);if(os==null)throw new IOException("Impossibile creare il file");BufferedWriter w=new BufferedWriter(new OutputStreamWriter(os,"UTF-8"));w.write('\ufeff');w.write("Data;Sport;Match;Mercato;Strategia;Minuto;Tranche;Stake %;Stake EUR;Quota;Risultato;Voto;Note\n");for(TradeDbHelper.Operation o:db.allOperations()){if(isMovement(o))continue;w.write(csv(o.date)+";"+csv(o.sport)+";"+csv(o.match)+";"+csv(o.marketType)+";"+csv(o.strategy)+";"+csv(o.minute)+";"+csv(o.tranche)+";"+one.format(o.stakePct)+";"+one.format(o.stakeEur)+";"+one.format(o.odds)+";"+one.format(o.result)+";"+csv(o.rating)+";"+csv(o.notes)+"\n");}w.flush();w.close();toast("CSV esportato: apribile con Excel");}
    private String csv(String s){if(s==null)return "";String x=s.replace("\"","\"\"");return "\""+x+"\"";}
    private void writeBackup(Uri uri)throws Exception{db.getWritableDatabase().rawQuery("PRAGMA wal_checkpoint(FULL)",null).close();File src=getDatabasePath("fastrade.db");InputStream in=new FileInputStream(src);OutputStream out=getContentResolver().openOutputStream(uri);if(out==null)throw new IOException("Impossibile creare backup");copy(in,out);in.close();out.close();toast("Backup completato");}
    private void readBackup(Uri uri)throws Exception{File dst=getDatabasePath("fastrade.db"),tmp=new File(getCacheDir(),"fastrade_restore.db");InputStream in=getContentResolver().openInputStream(uri);if(in==null)throw new IOException("File non leggibile");OutputStream out=new FileOutputStream(tmp);copy(in,out);in.close();out.close();db.close();InputStream bin=new FileInputStream(tmp);OutputStream bout=new FileOutputStream(dst,false);copy(bin,bout);bin.close();bout.close();new File(dst.getPath()+"-wal").delete();new File(dst.getPath()+"-shm").delete();db=new TradeDbHelper(this);toast("Dati ripristinati");showDashboard();}
    private void copy(InputStream in,OutputStream out)throws IOException{byte[] b=new byte[8192];int n;while((n=in.read(b))>0)out.write(b,0,n);out.flush();}
    private void confirmDeleteMovement(long id){new AlertDialog.Builder(this).setTitle("Elimina movimento?").setMessage("Il deposito o prelievo verrà eliminato e il bankroll sarà ricalcolato.").setPositiveButton("Elimina",(d,w)->{db.deleteOperation(id);bankTab=1;showBankroll();}).setNegativeButton("Annulla",null).show();}

    private void showStrategyManager(){page("Gestione Strategie",4);content.addView(action("＋ NUOVA STRATEGIA",GREEN,v->strategyDialog(null)));List<TradeDbHelper.Strategy> list=db.allStrategies(false);if(list.isEmpty()){content.addView(empty("Nessuna strategia personalizzata."));return;}for(TradeDbHelper.Strategy s:list){LinearLayout c=card(SURFACE);LinearLayout top=row();top.addView(text(s.name,14,TEXT,true),new LinearLayout.LayoutParams(0,-2,1));TextView st=text(s.active?"ATTIVA":"OFF",9,Color.WHITE,true);st.setGravity(Gravity.CENTER);st.setBackground(round(s.active?DARKGREEN:Color.DKGRAY,7,0));top.addView(st,new LinearLayout.LayoutParams(dp(56),dp(26)));c.addView(top);if(!s.description.isEmpty())c.addView(text(s.description,10,MUTED,false));c.addView(text("Stake default: "+one.format(s.defaultStakePct)+"%",10,BLUE,true));LinearLayout ac=row();Button edit=smallButton("MODIFICA",BLUE2);edit.setOnClickListener(v->strategyDialog(s));ac.addView(edit,wp());Button tg=smallButton(s.active?"DISATTIVA":"ATTIVA",SURFACE2);tg.setOnClickListener(v->{db.updateStrategy(s.id,s.name,s.description,s.defaultStakePct,!s.active);showStrategyManager();});ac.addView(tg,wp());c.addView(ac);content.addView(c);}}
    private void strategyDialog(TradeDbHelper.Strategy old){LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(dp(18),0,dp(18),0);EditText name=input(false,"Nome strategia"),desc=input(false,"Regole / descrizione"),stake=input(true,"2,0");if(old!=null){name.setText(old.name);desc.setText(old.description);stake.setText(one.format(old.defaultStakePct));}box.addView(field("Nome",name));box.addView(field("Descrizione",desc));box.addView(field("Stake default %",stake));new AlertDialog.Builder(this).setTitle(old==null?"Nuova strategia":"Modifica strategia").setView(box).setPositiveButton("Salva",(d,w)->{if(name.getText().toString().trim().isEmpty())return;if(old==null)db.addStrategy(name.getText().toString(),desc.getText().toString(),parse(stake.getText().toString()));else db.updateStrategy(old.id,name.getText().toString(),desc.getText().toString(),parse(stake.getText().toString()),old.active);showStrategyManager();}).setNegativeButton("Annulla",null).show();}

