    private void confirmDelete(long id){new AlertDialog.Builder(this).setTitle("Elimina operazione?").setMessage("L'operazione verrà rimossa dal diario e dalle statistiche.").setPositiveButton("Elimina",(d,w)->{db.deleteOperation(id);showJournal();}).setNegativeButton("Annulla",null).show();}

    private Stats stats(){Stats s=new Stats();s.startingBank=prefs.getFloat("starting_bank",0);for(TradeDbHelper.Operation o:db.allOperations()){if(isMovement(o)){if(o.result>=0)s.deposits+=o.result;else s.withdrawals+=o.result;continue;}s.totalTrades++;s.totalStake+=o.stakeEur;s.netProfit+=o.result;if(o.result>0)s.wins++;else if(o.result<0)s.losses++;}s.currentBank=s.startingBank+s.deposits+s.withdrawals+s.netProfit;s.winPct=s.totalTrades==0?0:(double)s.wins/s.totalTrades;s.roi=s.totalStake==0?0:s.netProfit/s.totalStake;return s;}
    private boolean isMovement(TradeDbHelper.Operation o){String m=o.market==null?"":o.market;return m.equalsIgnoreCase("DEPOSIT")||m.equalsIgnoreCase("WITHDRAW")||m.equalsIgnoreCase("DEPOSITO")||m.equalsIgnoreCase("PRELIEVO");}
    private List<Double> bankrollSeries(double start,int days){ArrayList<TradeDbHelper.Operation> chronological=new ArrayList<>(db.allOperations());Collections.reverse(chronological);SimpleDateFormat f=new SimpleDateFormat("dd/MM/yyyy",Locale.ITALY);Calendar today=Calendar.getInstance(Locale.ITALY);zeroTime(today);Calendar first=(Calendar)today.clone();first.add(Calendar.DAY_OF_YEAR,-Math.max(1,days)+1);double bank=start;for(TradeDbHelper.Operation o:chronological){try{Date d=f.parse(o.date);if(d.before(first.getTime()))bank+=o.result;}catch(Exception ignored){}}ArrayList<Double> vals=new ArrayList<>();Calendar day=(Calendar)first.clone();while(!day.after(today)){String ds=f.format(day.getTime());for(TradeDbHelper.Operation o:chronological)if(ds.equals(o.date))bank+=o.result;vals.add(bank);day.add(Calendar.DAY_OF_YEAR,1);}if(vals.size()<2)vals.add(bank);return vals;}
    private List<Double> profitSeries(int days){ArrayList<TradeDbHelper.Operation> chronological=new ArrayList<>(db.allOperations());Collections.reverse(chronological);SimpleDateFormat f=new SimpleDateFormat("dd/MM/yyyy",Locale.ITALY);Calendar today=Calendar.getInstance(Locale.ITALY);zeroTime(today);Calendar first=(Calendar)today.clone();first.add(Calendar.DAY_OF_YEAR,-Math.max(1,days)+1);double profit=0;for(TradeDbHelper.Operation o:chronological){if(isMovement(o))continue;try{Date d=f.parse(o.date);if(d.before(first.getTime()))profit+=o.result;}catch(Exception ignored){}}ArrayList<Double> vals=new ArrayList<>();Calendar day=(Calendar)first.clone();while(!day.after(today)){String ds=f.format(day.getTime());for(TradeDbHelper.Operation o:chronological)if(!isMovement(o)&&ds.equals(o.date))profit+=o.result;vals.add(profit);day.add(Calendar.DAY_OF_YEAR,1);}if(vals.size()<2)vals.add(profit);return vals;}
    private void zeroTime(Calendar c){c.set(Calendar.HOUR_OF_DAY,0);c.set(Calendar.MINUTE,0);c.set(Calendar.SECOND,0);c.set(Calendar.MILLISECOND,0);}
    private double todayProfit(){String d=new SimpleDateFormat("dd/MM/yyyy",Locale.ITALY).format(new Date());double x=0;for(TradeDbHelper.Operation o:db.allOperations())if(d.equals(o.date)&&!isMovement(o))x+=o.result;return x;}
    private int todayTrades(){String d=new SimpleDateFormat("dd/MM/yyyy",Locale.ITALY).format(new Date());int n=0;for(TradeDbHelper.Operation o:db.allOperations())if(d.equals(o.date)&&!isMovement(o))n++;return n;}
    private double dayTotal(String date){double x=0;for(TradeDbHelper.Operation o:db.allOperations())if(date.equals(o.date)&&!isMovement(o))x+=o.result;return x;}
    private double weekProfit(){Calendar now=Calendar.getInstance(Locale.ITALY);int wk=now.get(Calendar.WEEK_OF_YEAR),yr=now.get(Calendar.YEAR);SimpleDateFormat f=new SimpleDateFormat("dd/MM/yyyy",Locale.ITALY);double x=0;for(TradeDbHelper.Operation o:db.allOperations()){try{Calendar c=Calendar.getInstance(Locale.ITALY);c.setTime(f.parse(o.date));if(c.get(Calendar.WEEK_OF_YEAR)==wk&&c.get(Calendar.YEAR)==yr&&!isMovement(o))x+=o.result;}catch(Exception ignored){}}return x;}
    private List<TradeDbHelper.Operation> filteredOps(){List<TradeDbHelper.Operation> all=db.allOperations();if(journalFilter==0)return nonMovement(all);ArrayList<TradeDbHelper.Operation> out=new ArrayList<>();Calendar now=Calendar.getInstance(Locale.ITALY);SimpleDateFormat f=new SimpleDateFormat("dd/MM/yyyy",Locale.ITALY);for(TradeDbHelper.Operation o:all){if(isMovement(o))continue;try{Calendar c=Calendar.getInstance(Locale.ITALY);c.setTime(f.parse(o.date));boolean ok=journalFilter==1&&sameDay(c,now)||journalFilter==2&&c.get(Calendar.WEEK_OF_YEAR)==now.get(Calendar.WEEK_OF_YEAR)&&c.get(Calendar.YEAR)==now.get(Calendar.YEAR)||journalFilter==3&&c.get(Calendar.MONTH)==now.get(Calendar.MONTH)&&c.get(Calendar.YEAR)==now.get(Calendar.YEAR);if(ok)out.add(o);}catch(Exception ignored){}}return out;}
    private List<TradeDbHelper.Operation> nonMovement(List<TradeDbHelper.Operation> all){ArrayList<TradeDbHelper.Operation> x=new ArrayList<>();for(TradeDbHelper.Operation o:all)if(!isMovement(o))x.add(o);return x;}
    private boolean sameDay(Calendar a,Calendar b){return a.get(Calendar.YEAR)==b.get(Calendar.YEAR)&&a.get(Calendar.DAY_OF_YEAR)==b.get(Calendar.DAY_OF_YEAR);}
    private Map<String,SS> strategyMap(){Map<String,SS> map=new LinkedHashMap<>();for(TradeDbHelper.Operation o:db.allOperations()){if(isMovement(o))continue;String k=o.strategy.isEmpty()?o.market:o.strategy;SS x=map.get(k);if(x==null){x=new SS();map.put(k,x);}x.op++;if(o.result>0)x.win++;else if(o.result<0)x.lose++;x.profit+=o.result;x.stake+=o.stakeEur;}return map;}

