    private LinearLayout.LayoutParams wp(){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,-2,1);p.setMargins(dp(2),0,dp(2),0);return p;}
    private int dp(int n){return(int)(n*getResources().getDisplayMetrics().density+.5f);}
    private int dp(float n){return(int)(n*getResources().getDisplayMetrics().density+.5f);}
    private String sign(double x){return x>=0?"+ ":"- ";}
    private double parse(String s){if(s==null||s.trim().isEmpty())return 0;String v=s.trim().replace(" ","");if(v.contains(",")&&v.contains(".")){if(v.lastIndexOf(',')>v.lastIndexOf('.'))v=v.replace(".","").replace(',', '.');else v=v.replace(",","");}else v=v.replace(',', '.');try{return Double.parseDouble(v);}catch(Exception e){return 0;}}
    private void toast(String s){Toast.makeText(this,s,Toast.LENGTH_SHORT).show();}

    private static class Stats{double startingBank,currentBank,deposits,withdrawals,netProfit,totalStake,winPct,roi;int wins,losses,totalTrades;}
    private static class SS{int op,win,lose;double profit,stake;}
    private static class NavItem{LinearLayout box;TextView icon,label;int index;NavItem(LinearLayout b,TextView i,TextView l,int x){box=b;icon=i;label=l;index=x;}}

    private class HeroBankCard extends View{
        private final Stats s;private final Paint p=new Paint(1);HeroBankCard(Context c,Stats st){super(c);s=st;setLayerType(View.LAYER_TYPE_SOFTWARE,null);}
        @Override protected void onDraw(Canvas c){super.onDraw(c);float w=getWidth(),h=getHeight();RectF r=new RectF(0,0,w,h);Paint bg=new Paint(1);bg.setShader(new LinearGradient(0,0,w,h,Color.rgb(5,55,89),Color.rgb(4,27,48),Shader.TileMode.CLAMP));c.drawRoundRect(r,dp(18),dp(18),bg);Paint stroke=new Paint(1);stroke.setStyle(Paint.Style.STROKE);stroke.setStrokeWidth(dp(1));stroke.setColor(Color.rgb(22,92,135));c.drawRoundRect(r,dp(18),dp(18),stroke);Paint glow=new Paint(1);glow.setShader(new RadialGradient(w*.82f,h*.2f,w*.5f,Color.argb(95,0,255,185),Color.TRANSPARENT,Shader.TileMode.CLAMP));c.drawRoundRect(r,dp(18),dp(18),glow);
            p.setTypeface(Typeface.create("sans",Typeface.BOLD));p.setColor(Color.rgb(205,230,245));p.setTextSize(dp(11));c.drawText("CURRENT BANK",dp(16),dp(28),p);p.setColor(TEXT);p.setTextSize(dp(31));c.drawText(money.format(s.currentBank),dp(16),dp(68),p);p.setColor(s.netProfit>=0?GREEN:RED);p.setTextSize(dp(13));String change=sign(s.netProfit)+money.format(Math.abs(s.netProfit))+"   ("+(s.startingBank==0?"0,0%":pct.format(s.netProfit/s.startingBank))+")";c.drawText(change,dp(16),dp(94),p);
            List<Double> vals=bankrollSeries(s.startingBank,30);if(vals.size()>1){double min=Collections.min(vals),max=Collections.max(vals);if(max-min<1)max=min+1;Path path=new Path();float L=w*.48f,R=w-dp(15),T=h*.36f,B=h-dp(16);for(int i=0;i<vals.size();i++){float x=L+(R-L)*i/(vals.size()-1f);float y=(float)(B-(vals.get(i)-min)/(max-min)*(B-T));if(i==0)path.moveTo(x,y);else path.lineTo(x,y);}Paint line=new Paint(1);line.setStyle(Paint.Style.STROKE);line.setStrokeWidth(dp(2.2f));line.setColor(GREEN);line.setShadowLayer(dp(8),0,0,Color.argb(110,0,255,170));c.drawPath(path,line);Paint pt=new Paint(1);pt.setColor(CYAN);c.drawCircle(R,(float)(B-(vals.get(vals.size()-1)-min)/(max-min)*(B-T)),dp(3),pt);}
        }
    }

    private class MiniSpark extends View{private final int color,type;private final Paint p=new Paint(1);MiniSpark(Context c,int col,int t){super(c);color=col;type=t;}@Override protected void onDraw(Canvas c){super.onDraw(c);float w=getWidth(),h=getHeight();Path path=new Path();float[] ys=type==0?new float[]{.82f,.72f,.78f,.60f,.64f,.48f,.51f,.32f,.38f,.20f}:type==1?new float[]{.70f,.55f,.64f,.47f,.52f,.30f,.35f,.24f,.29f,.14f}:new float[]{.55f,.62f,.50f,.58f,.42f,.46f,.34f,.39f,.27f,.31f};for(int i=0;i<ys.length;i++){float x=dp(2)+(w-dp(4))*i/(ys.length-1f),y=h*ys[i];if(i==0)path.moveTo(x,y);else path.lineTo(x,y);}p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(dp(1.5f));p.setColor(color);c.drawPath(path,p);}}

    private class BankrollChart extends View{
        private final List<Double> vals; private final int days; private final boolean callout; private final Paint p=new Paint(1),grid=new Paint(1),label=new Paint(1);
        BankrollChart(Context c,List<Double> v,int d,boolean co){super(c);vals=v;days=d;callout=co;grid.setColor(Color.rgb(25,55,73));grid.setStrokeWidth(dp(1));p.setStrokeWidth(dp(2.2f));p.setStyle(Paint.Style.STROKE);p.setColor(BLUE);p.setStrokeCap(Paint.Cap.ROUND);label.setColor(MUTED);label.setTextSize(dp(8));setLayerType(View.LAYER_TYPE_SOFTWARE,null);}
        @Override protected void onDraw(Canvas c){super.onDraw(c);int w=getWidth(),h=getHeight();float L=dp(38),R=w-dp(10),T=dp(14),B=h-dp(28);for(int i=0;i<4;i++){float y=T+(B-T)*i/3f;c.drawLine(L,y,R,y,grid);}if(vals==null||vals.size()<2)return;double min=Collections.min(vals),max=Collections.max(vals);double pad=Math.max(1,(max-min)*.15);min-=pad;max+=pad;label.setTextSize(dp(8));for(int i=0;i<4;i++){double v=max-(max-min)*i/3d;String s=v>=1000?one.format(v/1000d)+"k":String.valueOf((int)v);c.drawText(s,dp(2),T+(B-T)*i/3f+dp(3),label);}Path path=new Path();for(int i=0;i<vals.size();i++){float x=L+(R-L)*i/(vals.size()-1f);float y=(float)(B-(vals.get(i)-min)/(max-min)*(B-T));if(i==0)path.moveTo(x,y);else path.lineTo(x,y);}Paint fill=new Paint(1);fill.setShader(new LinearGradient(0,T,0,B,Color.argb(105,25,135,255),Color.TRANSPARENT,Shader.TileMode.CLAMP));Path area=new Path(path);area.lineTo(R,B);area.lineTo(L,B);area.close();c.drawPath(area,fill);p.setShadowLayer(dp(8),0,0,Color.argb(90,25,135,255));c.drawPath(path,p);p.clearShadowLayer();float ly=(float)(B-(vals.get(vals.size()-1)-min)/(max-min)*(B-T));Paint pt=new Paint(1);pt.setColor(GREEN);pt.setShadowLayer(dp(7),0,0,GREEN);c.drawCircle(R,ly,dp(3.5f),pt);pt.clearShadowLayer();Calendar end=Calendar.getInstance(Locale.ITALY),mid=(Calendar)end.clone(),start=(Calendar)end.clone();start.add(Calendar.DAY_OF_YEAR,-days+1);mid.add(Calendar.DAY_OF_YEAR,-days/2);SimpleDateFormat df=new SimpleDateFormat(days>=365?"MMM yy":"d MMM",Locale.ITALY);String a=df.format(start.getTime()),m=df.format(mid.getTime()),z=df.format(end.getTime());c.drawText(a,L,B+dp(18),label);float mw=label.measureText(m);c.drawText(m,(L+R)/2-mw/2,B+dp(18),label);float zw=label.measureText(z);c.drawText(z,R-zw,B+dp(18),label);if(callout){String v=money.format(vals.get(vals.size()-1));float tw=label.measureText(v)+dp(22);float bx=Math.max(L,R-tw),by=Math.max(T+dp(4),ly-dp(35));Paint bubble=new Paint(1);bubble.setColor(Color.rgb(13,34,52));c.drawRoundRect(new RectF(bx,by,R,by+dp(28)),dp(7),dp(7),bubble);label.setColor(TEXT);label.setTextSize(dp(8.5f));c.drawText(v,bx+dp(9),by+dp(18),label);label.setColor(MUTED);}}
    }

    private class DualLineChart extends View{private final List<Double> bank,profit;private final int days;DualLineChart(Context c,List<Double>b,List<Double>p,int d){super(c);bank=b;profit=p;days=d;setLayerType(View.LAYER_TYPE_SOFTWARE,null);}@Override protected void onDraw(Canvas c){super.onDraw(c);float w=getWidth(),h=getHeight(),L=dp(36),R=w-dp(10),T=dp(28),B=h-dp(28);Paint grid=new Paint(1);grid.setColor(Color.rgb(25,55,73));for(int i=0;i<4;i++){float y=T+(B-T)*i/3f;c.drawLine(L,y,R,y,grid);}drawSeries(c,bank,L,R,T,B,BLUE,true);drawSeries(c,profit,L,R,T,B,GREEN,false);Paint lab=new Paint(1);lab.setTextSize(dp(8));lab.setColor(MUTED);lab.setTypeface(Typeface.create("sans",Typeface.NORMAL));c.drawText("● Bankroll",L,T-dp(9),lab);lab.setColor(GREEN);c.drawText("● Profitto",L+dp(72),T-dp(9),lab);Calendar end=Calendar.getInstance(Locale.ITALY),start=(Calendar)end.clone();start.add(Calendar.DAY_OF_YEAR,-days+1);SimpleDateFormat df=new SimpleDateFormat(days>=365?"MMM yy":"d MMM",Locale.ITALY);lab.setColor(MUTED);c.drawText(df.format(start.getTime()),L,B+dp(18),lab);String z=df.format(end.getTime());c.drawText(z,R-lab.measureText(z),B+dp(18),lab);}
        private void drawSeries(Canvas c,List<Double>vals,float L,float R,float T,float B,int col,boolean fillIt){if(vals==null||vals.size()<2)return;double min=Collections.min(vals),max=Collections.max(vals);if(Math.abs(max-min)<1)max=min+1;Path path=new Path();for(int i=0;i<vals.size();i++){float x=L+(R-L)*i/(vals.size()-1f),y=(float)(B-(vals.get(i)-min)/(max-min)*(B-T));if(i==0)path.moveTo(x,y);else path.lineTo(x,y);}if(fillIt){Paint fill=new Paint(1);fill.setShader(new LinearGradient(0,T,0,B,Color.argb(65,25,135,255),Color.TRANSPARENT,Shader.TileMode.CLAMP));Path a=new Path(path);a.lineTo(R,B);a.lineTo(L,B);a.close();c.drawPath(a,fill);}Paint line=new Paint(1);line.setStyle(Paint.Style.STROKE);line.setStrokeWidth(dp(2));line.setColor(col);line.setStrokeCap(Paint.Cap.ROUND);c.drawPath(path,line);}}

    private class ProfitBars extends View{private final List<Map.Entry<String,SS>> entries=new ArrayList<>();ProfitBars(Context c,Map<String,SS> m){super(c);entries.addAll(m.entrySet());Collections.sort(entries,(a,b)->Double.compare(Math.abs(b.getValue().profit),Math.abs(a.getValue().profit)));if(entries.size()>7)entries.subList(7,entries.size()).clear();}@Override protected void onDraw(Canvas c){super.onDraw(c);Paint p=new Paint(1),lab=new Paint(1);lab.setTextSize(dp(9));lab.setColor(MUTED);float w=getWidth(),row=dp(31),top=dp(10),left=dp(95),right=w-dp(16);double max=1;for(Map.Entry<String,SS>e:entries)max=Math.max(max,Math.abs(e.getValue().profit));for(int i=0;i<entries.size();i++){Map.Entry<String,SS>e=entries.get(i);float y=top+i*row;String name=e.getKey();if(name.length()>16)name=name.substring(0,15)+"…";c.drawText(name,dp(8),y+dp(18),lab);float len=(float)((right-left)*Math.abs(e.getValue().profit)/max);p.setColor(e.getValue().profit>=0?GREEN:RED);c.drawRoundRect(new RectF(left,y+dp(7),left+len,y+dp(20)),dp(5),dp(5),p);lab.setColor(TEXT);String v=money.format(e.getValue().profit);c.drawText(v,Math.min(right-lab.measureText(v),left+len+dp(6)),y+dp(18),lab);lab.setColor(MUTED);}}}

    private class DonutCard extends View{private final List<Map.Entry<String,SS>> entries=new ArrayList<>();DonutCard(Context c,Map<String,SS> m){super(c);entries.addAll(m.entrySet());}@Override protected void onDraw(Canvas c){super.onDraw(c);float w=getWidth(),h=getHeight(),cx=dp(88),cy=h/2f,rad=dp(57);double total=0;for(Map.Entry<String,SS>e:entries)if(e.getValue().profit>0)total+=e.getValue().profit;Paint p=new Paint(1);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(dp(18));p.setStrokeCap(Paint.Cap.BUTT);int[] cols={BLUE,GREEN,CYAN,GOLD,PURPLE,Color.rgb(112,165,212)};float start=-90;int idx=0;for(Map.Entry<String,SS>e:entries){if(e.getValue().profit<=0)continue;float sweep=total<=0?0:(float)(360d*e.getValue().profit/total);p.setColor(cols[idx%cols.length]);c.drawArc(new RectF(cx-rad,cy-rad,cx+rad,cy+rad),start,sweep,false,p);start+=sweep;idx++;}Paint lab=new Paint(1);lab.setTypeface(Typeface.create("sans",Typeface.BOLD));lab.setTextAlign(Paint.Align.CENTER);lab.setColor(TEXT);lab.setTextSize(dp(13));c.drawText(money.format(total),cx,cy-dp(2),lab);lab.setTextSize(dp(8));lab.setColor(MUTED);c.drawText("Profitto Totale",cx,cy+dp(14),lab);lab.setTextAlign(Paint.Align.LEFT);float x=dp(170),y=dp(26);idx=0;for(Map.Entry<String,SS>e:entries){if(e.getValue().profit<=0)continue;if(y>h-dp(16))break;p.setStyle(Paint.Style.FILL);p.setColor(cols[idx%cols.length]);c.drawCircle(x,y,dp(4),p);lab.setColor(TEXT);lab.setTextSize(dp(9));String name=e.getKey();if(name.length()>15)name=name.substring(0,14)+"…";c.drawText(name,x+dp(10),y+dp(3),lab);lab.setColor(MUTED);String share=total<=0?"0%":((int)Math.round(100*e.getValue().profit/total))+"%";c.drawText(share,w-dp(38),y+dp(3),lab);y+=dp(24);idx++;}}}

    private class WaveDecoration extends View{WaveDecoration(Context c){super(c);setLayerType(View.LAYER_TYPE_SOFTWARE,null);}@Override protected void onDraw(Canvas c){super.onDraw(c);float w=getWidth(),h=getHeight();int[] cols={CYAN,BLUE,PURPLE};for(int k=0;k<3;k++){Path path=new Path();path.moveTo(0,h*(.75f-k*.08f));for(int i=0;i<=20;i++){float x=w*i/20f;float y=(float)(h*(.55f-k*.05f)+Math.sin(i*.45+k)*h*.16);path.lineTo(x,y);}Paint p=new Paint(1);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(dp(1.3f));p.setColor(cols[k]);p.setAlpha(130-k*20);p.setShadowLayer(dp(8),0,0,cols[k]);c.drawPath(path,p);}}}
